<template><div class="app-container wish-admin"><div class="wa-heading"><div><h2>心愿互助</h2><p>审核发布内容与资质，处理争议，核对服务者结算。</p></div><el-tag type="info">成本 + 1% 展示 · 完成后收取 5%</el-tag></div><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="心愿与订单" name="wishes"/><el-tab-pane label="资质 / 收款资料" name="credentials"/></el-tabs>
  <template v-if="tab==='wishes'"><el-form inline><el-form-item label="订单状态"><el-select v-model="status" clearable placeholder="全部状态" style="width:180px" @change="page=1;load()"><el-option v-for="(label,key) in states" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item><el-button @click="load">刷新</el-button></el-form-item></el-form><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="wishId" label="编号" width="80"/><el-table-column prop="title" label="心愿" min-width="200" show-overflow-tooltip/><el-table-column prop="publisherName" label="发布者" width="110"/><el-table-column prop="helperName" label="服务者" width="110"/><el-table-column label="城市" min-width="160"><template #default="{row}">{{row.targetCity}} → {{row.originCity}}</template></el-table-column><el-table-column label="展示价" width="110"><template #default="{row}">¥{{money(row.amountFen)}}</template></el-table-column><el-table-column label="状态" width="140"><template #default="{row}"><el-tag>{{states[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="结算" width="120"><template #default="{row}">{{row.payoutStatus==='paid'?'已登记打款':row.payoutStatus==='pending'?'待打款':'—'}}</template></el-table-column><el-table-column label="操作" fixed="right" width="100"><template #default="{row}"><el-button link type="primary" @click="open(row.wishId)">查看处理</el-button></template></el-table-column></el-table><pagination v-show="total>0" v-model:page="page" :limit="20" :total="total" @pagination="load"/></template>
  <template v-else><el-alert type="info" :closable="false" title="证照、收款资料为私有文件，链接10分钟有效。食品需有效健康证或食品经营许可证；烟酒许可需核实适用地区及许可范围。"/><div class="wa-refresh"><el-input v-model="credentialUser" placeholder="按用户ID筛选资质 / 收款资料" clearable style="width:280px;margin-right:12px" @clear="load" @keyup.enter="load"/><el-button @click="load">查询资料</el-button><span style="margin-left:12px;color:#8492a6;font-size:12px">显示最近100条记录</span></div><el-table v-loading="loading" :data="credentials"><el-table-column prop="credentialId" label="编号" width="80"/><el-table-column prop="nickname" label="用户" width="110"/><el-table-column prop="userId" label="用户ID" width="90"/><el-table-column label="类型" min-width="160"><template #default="{row}">{{types[row.type]}}</template></el-table-column><el-table-column prop="city" label="适用城市"/><el-table-column label="有效期" min-width="190"><template #default="{row}">{{row.type==='payout'?'—':(row.validFrom||'待核实')+' 至 '+(row.validUntil||'待核实')}}</template></el-table-column><el-table-column label="许可范围" width="120"><template #default="{row}">{{row.type==='permit'?({2:'烟草',4:'酒类',6:'烟草及酒类'})[row.permitScope]||'待核实':'—'}}</template></el-table-column><el-table-column label="审核状态"><template #default="{row}">{{credentialStates[row.status]}}</template></el-table-column><el-table-column prop="note" label="审核说明" min-width="180" show-overflow-tooltip/><el-table-column label="文件 / 审核" width="245"><template #default="{row}"><el-link :href="asset(row.url)" target="_blank" rel="noopener noreferrer" type="primary">查看私有文件</el-link><el-button v-hasPermi="['kangaroo:wish:edit']" link type="success" @click="review(row,true)">通过</el-button><el-button v-hasPermi="['kangaroo:wish:edit']" link type="danger" @click="review(row,false)">{{row.status==='approved'?'撤销':'驳回'}}</el-button></template></el-table-column></el-table></template>
  <el-drawer v-model="drawer" title="心愿详情与处理" size="min(760px, 95vw)"><template v-if="detail"><h2>{{detail.title}}</h2><el-descriptions :column="2" border><el-descriptions-item label="订单">#{{detail.wishId}} · {{states[detail.status]}}</el-descriptions-item><el-descriptions-item label="类别">{{categories[detail.category]}}</el-descriptions-item><el-descriptions-item label="发布者">{{detail.publisherName}}（{{detail.publisherId}}）</el-descriptions-item><el-descriptions-item label="服务者">{{detail.helperName||'尚未接单'}}（{{detail.helperId||'—'}}）</el-descriptions-item><el-descriptions-item label="城市">{{detail.targetCity}} → {{detail.originCity}}</el-descriptions-item><el-descriptions-item label="期望完成">{{detail.deadline}}</el-descriptions-item><el-descriptions-item label="成本">¥{{money(detail.costFen)}}</el-descriptions-item><el-descriptions-item label="发布加价 1%">¥{{money(detail.markupFen)}}</el-descriptions-item><el-descriptions-item label="展示价 / 实付应收">¥{{money(detail.amountFen)}}</el-descriptions-item><el-descriptions-item label="完成手续费 5%">¥{{money(detail.feeFen)}}</el-descriptions-item><el-descriptions-item label="服务者结算">¥{{money(detail.netFen)}}</el-descriptions-item><el-descriptions-item label="打款状态">{{detail.payoutStatus==='paid'?'已登记打款':detail.payoutStatus==='pending'?'待打款':'无需打款'}}</el-descriptions-item><el-descriptions-item v-if="detail.delivery==='express'" label="快递公司">{{detail.courier||'尚未填写'}}</el-descriptions-item><el-descriptions-item v-if="detail.delivery==='express'" label="快递单号">{{detail.trackingNo||'尚未填写'}}</el-descriptions-item></el-descriptions><h3>心愿要求</h3><p class="wa-copy">{{detail.description}}</p><div class="wa-images"><el-image v-for="src in split(detail.images)" :key="src" :src="asset(src)" :preview-src-list="split(detail.images).map(asset)" fit="cover"/></div><template v-if="detail.proof"><h3>交付凭证</h3><p class="wa-copy">{{detail.deliveryNote}}</p><div class="wa-images"><el-image v-for="src in split(detail.proof)" :key="src" :src="asset(src)" :preview-src-list="split(detail.proof).map(asset)" fit="cover"/></div></template><el-alert v-if="detail.dispute" type="warning" :closable="false" :title="'争议说明：'+detail.dispute"/><el-alert v-if="detail.auditNote" type="info" :closable="false" :title="'审核说明：'+detail.auditNote"/>
    <div v-hasPermi="['kangaroo:wish:edit']" class="wa-actions"><el-button v-if="detail.helperId && detail.mode==='paid'" @click="viewPayee">查看服务者收款资料</el-button><template v-if="detail.status==='reviewing'"><el-button type="primary" @click="action('approve')">审核通过并展示</el-button><el-button type="danger" @click="action('reject')">驳回并全额退款</el-button></template><el-button v-if="detail.status==='open'" type="danger" @click="action('reject')">下架并全额退款</el-button><template v-if="detail.status==='disputed'"><el-button @click="action('resume')">恢复履约</el-button><el-button type="warning" @click="action('refund')">全额退款并关闭</el-button><el-button type="primary" @click="action('complete')">裁定完成并结算</el-button></template><el-button v-if="detail.status==='refund_failed'" type="warning" @click="action('refund')">重新申请退款</el-button><el-button v-if="detail.status==='completed'&&detail.payoutStatus==='pending'" type="success" @click="payoutOpen=true;payout={receipt:'',amount:'',note:''}">登记实际打款</el-button></div>
    <el-alert v-if="detail.eligibilityError" type="error" :closable="false" :title="detail.eligibilityError"/>
    <el-descriptions :column="1" border><el-descriptions-item label="交付性质">{{detail.informationOnly?'已核实为线上信息咨询':'按实际内容与交付方式核实'}}</el-descriptions-item><el-descriptions-item label="已检测 / 已复核范围">{{(detail.detectedTypes||[]).map(t=>complianceTypes[t]).join('、')||'需核实'}}</el-descriptions-item><el-descriptions-item label="交付时资质核验">{{detail.fulfillmentQualification?'已有资质快照':'尚无资质快照，可核实历史交付或处理争议退款'}}</el-descriptions-item></el-descriptions>
    <div v-hasPermi="['kangaroo:wish:edit']" class="wa-actions"><el-button v-if="['open','accepted','submitted','disputed'].includes(detail.status)" @click="action('classify')">复核实际品类</el-button><el-button v-if="['submitted','disputed'].includes(detail.status)" @click="action('verifyFulfillment')">核实历史交付资质</el-button></div>
    <el-collapse><el-collapse-item title="订单沟通记录（最近100条）"><div v-for="m in detail.messages" :key="m.messageId" class="wa-chat"><small>{{m.nickname}} · {{m.createTime}}</small><p v-if="m.content">{{m.content}}</p><div v-if="m.images?.length" class="wa-images"><el-image v-for="(src,i) in m.images" :key="src" :src="asset(src)" :preview-src-list="m.images.map(asset)" :initial-index="i" fit="cover"/></div></div></el-collapse-item><el-collapse-item title="操作审计记录"><el-timeline><el-timeline-item v-for="a in detail.history" :key="a.auditId" :timestamp="a.createTime">{{a.actor}} · {{actions[a.action]||a.action}}<p>{{a.note}}</p></el-timeline-item></el-timeline></el-collapse-item></el-collapse>
  </template></el-drawer>
  <el-dialog v-model="payoutOpen" title="登记实际打款" width="520px"><el-alert type="warning" :closable="false" title="此操作仅登记已经完成的真实打款，不会自动转账。请核对服务者已审核的收款资料、实际金额与银行流水。"/><el-form label-position="top" class="wa-payout"><el-form-item label="实际打款金额（元）"><el-input v-model="payout.amount" :placeholder="detail?'应为 '+money(detail.netFen):''"/></el-form-item><el-form-item label="银行 / 支付渠道交易流水号（至少6位，全平台唯一）"><el-input v-model="payout.receipt" maxlength="100"/></el-form-item><el-form-item label="核对说明"><el-input v-model="payout.note" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="payoutOpen=false">取消</el-button><el-button type="primary" :loading="mutating" @click="recordPayout">确认已实际打款</el-button></template></el-dialog>
  <el-dialog v-model="complianceOpen" :title="actions[complianceAction]" width="600px">
    <el-alert type="warning" :closable="false" title="文字筛查无法识别全部语义和图片。请查看原始内容、图片及交付凭证，核实实际商品。检测出的范围及此前复核范围默认不能取消；确认是文字误判（例如「咖啡色钱包」被当成食品）时，勾选下方「关键词误判」后按实际品类选择，所选类目和交付说明涉及的范围仍要保留。"/>
    <el-form label-position="top" class="wa-payout">
      <template v-if="complianceAction!=='verifyFulfillment'">
        <el-form-item label="实际涉及品类"><el-checkbox-group v-model="compliance.complianceTypes"><el-checkbox v-for="(label,key) in complianceTypes" :key="key" :label="key">{{label}}</el-checkbox></el-checkbox-group></el-form-item>
        <el-form-item><el-checkbox v-model="compliance.keywordMisjudged">关键词误判：以本次人工核实的品类为准，去掉系统按文字检测出的范围（会记入审计记录）</el-checkbox></el-form-item>
        <el-form-item v-if="detail.delivery==='digital' && detail.category!=='licensed'"><el-checkbox v-model="compliance.informationOnly" @change="value => { if(value) compliance.complianceTypes=['ordinary'] }">已核实为纯信息咨询（如美食攻略问答），不涉及采购、制作、寄送或实物交付</el-checkbox></el-form-item>
        <el-form-item><el-checkbox v-model="compliance.contentChecked">已人工核对正文、原始图片及实际商品，确认无禁止品类</el-checkbox></el-form-item>
      </template>
      <template v-else>
        <el-form-item label="实际交付日期"><el-date-picker v-model="compliance.serviceDate" type="date" value-format="YYYY-MM-DD"/></el-form-item>
        <el-form-item><el-checkbox v-model="compliance.fulfillmentChecked">已核实交付凭证、日期与当时有效的服务者资质</el-checkbox></el-form-item>
        <el-alert type="info" :closable="false" title="系统仍会核验证照在该日期是否有效。缺少证照时，可在资质审核中核实历史证件，或通过争议处理全额退款。"/>
      </template>
      <el-form-item label="核实依据与说明"><el-input v-model="compliance.note" type="textarea" maxlength="500" show-word-limit/></el-form-item>
    </el-form>
    <template #footer><el-button @click="complianceOpen=false">取消</el-button><el-button type="primary" :loading="mutating" @click="saveCompliance">确认核实结果</el-button></template>
  </el-dialog>
  <el-dialog v-model="credentialOpen" title="核实证件与适用范围" width="600px">
    <el-alert type="warning" :closable="false" title="请打开私有文件核对实际证件。已过期证件可记录历史有效期，系统只允许用于对应历史交付核验。"/>
    <el-form label-position="top" class="wa-payout">
      <el-form-item label="证件文件"><el-link :href="asset(credentialForm.url)" target="_blank" rel="noopener noreferrer" type="primary">查看证件原件</el-link></el-form-item>
      <template v-if="credentialForm.type!=='payout'">
        <el-form-item label="生效日期"><el-date-picker v-model="credentialForm.validFrom" type="date" value-format="YYYY-MM-DD"/></el-form-item>
        <el-form-item label="有效期止"><el-date-picker v-model="credentialForm.validUntil" type="date" value-format="YYYY-MM-DD"/></el-form-item>
      </template>
      <template v-if="credentialForm.type==='permit'">
        <el-form-item label="实际适用城市"><el-input v-model="credentialForm.city" maxlength="80"/></el-form-item>
        <el-form-item label="许可实际范围"><el-radio-group v-model="credentialForm.permitType"><el-radio label="tobacco">烟草</el-radio><el-radio label="alcohol">酒类</el-radio><el-radio label="both">烟草及酒类</el-radio></el-radio-group></el-form-item>
      </template>
      <el-form-item><el-checkbox v-model="credentialForm.documentChecked">已核实证件真实性、日期与适用范围</el-checkbox></el-form-item>
      <el-form-item label="审核依据"><el-input v-model="credentialForm.note" type="textarea" maxlength="500"/></el-form-item>
    </el-form>
    <template #footer><el-button @click="credentialOpen=false">取消</el-button><el-button type="primary" :loading="mutating" @click="approveCredential">保存审核结果</el-button></template>
  </el-dialog>
</div></template>
<script setup>
import { ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import request from '@/utils/request'
const states={pending_payment:'待支付',reviewing:'待审核',open:'等待接单',accepted:'履约中',submitted:'待确认',completed:'已完成',disputed:'争议处理中',refunding:'退款中',refund_failed:'退款未完成',cancelled:'已取消'}
const types={health:'健康证',food:'食品经营许可证',permit:'当地特殊许可',payout:'收款资料'},categories={craft:'文创手作',souvenir:'地方好物',postcard:'拍照寄语',errand:'生活互助',food:'食品类',licensed:'烟酒特殊许可'},credentialStates={pending:'待审核',approved:'已通过',rejected:'未通过'}
const actions={publish:'发布',paid:'支付确认',approve:'审核通过',reject:'驳回 / 下架',accept:'接单',tracking:'更新物流',deliver:'提交凭证',complete:'确认完成',cancel:'取消',refund:'退款',resume:'恢复履约',dispute:'申请介入',review:'评价',payout:'登记打款'}
const credentialUser=ref('')
const complianceTypes={ordinary:'普通品类',food:'食品',tobacco:'烟草',alcohol:'酒类'}
const complianceOpen=ref(false),complianceAction=ref('approve'),compliance=ref({})
const credentialOpen=ref(false),credentialForm=ref({})
Object.assign(actions,{classify:'复核实际品类',verifyFulfillment:'核实历史交付资质'})
const tab=ref('wishes'),status=ref('reviewing'),page=ref(1),total=ref(0),rows=ref([]),credentials=ref([]),loading=ref(false),drawer=ref(false),detail=ref(null),payoutOpen=ref(false),mutating=ref(false),payout=ref({receipt:'',amount:'',note:''})
const money=n=>(Number(n||0)/100).toFixed(2),split=s=>String(s||'').split(',').filter(Boolean),asset=p=>/^\/(profile|kangaroo)\//.test(p)?import.meta.env.VITE_APP_BASE_API+p:p
let revision=0
async function load(){const v=++revision;loading.value=true;try{if(tab.value==='credentials'){const r=await request({url:'/kangaroo/wishes/credentials',params:{userId:credentialUser.value||undefined}});if(v===revision)credentials.value=r.data}else{const r=await request({url:'/kangaroo/wishes',params:{status:status.value,pageNum:page.value}});if(v===revision){rows.value=r.data.rows;total.value=r.data.total}}}finally{if(v===revision)loading.value=false}}
function viewPayee(){credentialUser.value=String(detail.value.helperId);drawer.value=false;tab.value='credentials';load()}
async function open(id){detail.value=null;drawer.value=true;detail.value=(await request({url:'/kangaroo/wishes/'+id})).data}
async function review(row,approved){if(approved){credentialForm.value={...row,validFrom:row.validFrom||'',validUntil:row.validUntil||'',permitType:({2:'tobacco',4:'alcohol',6:'both'})[row.permitScope]||'',documentChecked:false,note:''};credentialOpen.value=true;return}try{const {value}=await ElMessageBox.prompt('填写驳回或撤销的具体原因。','审核'+types[row.type],{inputValidator:v=>!!v?.trim()&&v.length<=500||'请填写1至500字的说明'});await request({url:`/kangaroo/wishes/credentials/${row.credentialId}/review`,method:'post',data:{approved:false,note:value}});ElMessage.success('审核结果已保存');await load()}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
async function approveCredential(){if(mutating.value)return;const f=credentialForm.value;if(!f.documentChecked||!f.note.trim()||(f.type!=='payout'&&(!f.validFrom||!f.validUntil))){ElMessage.warning('请完成证件核对并填写有效期与说明');return}mutating.value=true;try{await request({url:`/kangaroo/wishes/credentials/${f.credentialId}/review`,method:'post',data:{...f,approved:true}});credentialOpen.value=false;ElMessage.success('审核结果已保存');await load()}catch(error){/* 请求拦截器展示具体原因，保留表单供修正。 */}finally{mutating.value=false}}
function openCompliance(name){complianceAction.value=name;compliance.value={complianceTypes:[...(detail.value.detectedTypes||[])],keywordMisjudged:false,informationOnly:!!detail.value.informationOnly,contentChecked:false,fulfillmentChecked:false,serviceDate:'',note:''};complianceOpen.value=true}
async function saveCompliance(){if(mutating.value)return;if(!compliance.value.note.trim()){ElMessage.warning('请填写核实依据');return}mutating.value=true;try{await request({url:`/kangaroo/wishes/${detail.value.wishId}/${complianceAction.value}`,method:'post',data:compliance.value});complianceOpen.value=false;ElMessage.success('核实结果已记录');await open(detail.value.wishId);await load()}catch(error){/* 请求拦截器展示具体原因，保留表单供修正。 */}finally{mutating.value=false}}
async function action(name){if(mutating.value)return;if(['approve','classify','verifyFulfillment'].includes(name)){openCompliance(name);return}try{const {value}=await ElMessageBox.prompt('请填写处理依据。退款将退回全部实付金额；争议完成操作会产生服务者待打款金额。',actions[name],{inputValidator:v=>!!v?.trim()&&v.length<=500||'请填写1至500字的说明'});mutating.value=true;await request({url:`/kangaroo/wishes/${detail.value.wishId}/${name}`,method:'post',data:{note:value}});ElMessage.success('处理已保存');await open(detail.value.wishId);await load()}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}finally{mutating.value=false}}
async function recordPayout(){if(mutating.value)return;const p=payout.value;if(!/^\d+(\.\d{1,2})?$/.test(p.amount)||Math.round(Number(p.amount)*100)!==detail.value.netFen||p.receipt.trim().length<6||!p.note.trim()){ElMessage.warning('请核对金额并填写完整流水号与说明');return}mutating.value=true;try{await request({url:`/kangaroo/wishes/${detail.value.wishId}/payout`,method:'post',data:{receipt:p.receipt.trim(),amountFen:detail.value.netFen,note:p.note.trim()}});payoutOpen.value=false;ElMessage.success('实际打款已登记');await open(detail.value.wishId);await load()}finally{mutating.value=false}}
load()
</script>
<style scoped>.wa-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.wa-heading h2{margin:0;color:#102c46}.wa-heading p{color:#7b8795;font-size:13px}.wa-refresh{margin:16px 0}.wa-copy{white-space:pre-wrap;line-height:1.8;color:#546477}.wa-images{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}.wa-images .el-image{width:130px;height:130px;border-radius:12px}.wa-actions{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.wa-actions .el-button{margin:0}.wa-chat{border-bottom:1px solid #edf0f5;padding:10px 0}.wa-chat p{white-space:pre-wrap;word-break:break-word}.wa-chat small{color:#8a97a7}.wa-payout{margin-top:20px}.wish-admin :deep(.el-alert){margin-top:12px}</style>
